    { "x-csrf-token": "" },
    { "x-csrf-token": "tampered" },
    { origin: "https://evil.example" },
  ])
    expect(
      (await f.request("auth/logout", {}, "POST", headers)).statusCode,
    ).toBe(403);
  expect((await f.request("auth/me")).statusCode).toBe(200);
});
