    };
    running = child("apps/api/src/main.ts", env);
    await running.started();
    const url = `http://127.0.0.1:${port}/api/v1/auth/me`;
    expect(
      (await fetch(url, { headers: { cookie: originalCookie } })).status,
    ).toBe(200);
